package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class ReportStore {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void recordOk(String date) {
        count(date, 0);
    }

    public void recordRejected(String date) {
        if (date != null) count(date, 1);
    }

    private void count(String date, int slot) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    public String generateReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    public BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) return new BigDecimal("4.30");
        if ("USD".equals(currency)) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger;

public class InstructionParser {
    public record Parsed(String verb, String date, String[] fields) {}

    public Parsed parse(String line) {
        if (line == null || line.trim().isEmpty()) throw new ParseException("BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> throw new ParseException("BAD_INSTRUCTION", "unknown verb " + verb);
        };
        if (f.length != want) throw new ParseException("BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) throw new ParseException("BAD_DATE", date);
        return new Parsed(verb, date, f);
    }

    public static class ParseException extends RuntimeException {
        public final String code;
        public final String message;
        public ParseException(String code, String message) {
            this.code = code;
            this.message = message;
        }
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class TransactionEngine {
    private final AccountStore as;
    private final TransactionStore ts;
    private final ReportStore rs;
    private final CurrencyConverter cc;

    public TransactionEngine(AccountStore as, TransactionStore ts, ReportStore rs, CurrencyConverter cc) {
        this.as = as; this.ts = ts; this.rs = rs; this.cc = cc;
    }

    public String transfer(String date, String fromId, String toId, BigDecimal amount, String currency) {
        Account from = as.getAccount(fromId);
        if (from == null) return "REJECTED UNKNOWN_ACCOUNT: " + fromId;
        Account to = as.getAccount(toId);
        if (to == null) return "REJECTED UNKNOWN_ACCOUNT: " + toId;
        if (fromId.equals(toId)) return "REJECTED SAME_ACCOUNT: cannot transfer to the same account";
        if (!from.currency.equals(currency)) return "REJECTED CURRENCY_MISMATCH: " + fromId + " holds " + from.currency;

        BigDecimal fee = calculateTransferFee(from.tier, amount);
        String rejection = checkLimitAndFunds(date, fromId, from, amount, fee);
        if (rejection != null) return "REJECTED " + rejection;

        BigDecimal credited = from.currency.equals(to.currency) ? amount : cc.convert(amount, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        as.addUsage(fromId, date, amount);
        rs.addFee(date, from.currency, fee);

        Transaction tx = new Transaction("TRANSFER", date, fromId, toId, amount, from.currency, fee, credited);
        return "OK TX-" + String.format("%06d", ts.save(tx).substring(3)) + " fee=" + fee + " " + from.currency;
    }

    private BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            return amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            return amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public String withdraw(String date, String id, BigDecimal amount) {
        Account a = as.getAccount(id);
        if (a == null) return "REJECTED UNKNOWN_ACCOUNT: " + id;
        BigDecimal fee = "STANDARD".equals(a.tier) ? new BigDecimal("1.00") : new BigDecimal("0.00");
        String rejection = checkLimitAndFunds(date, id, a, amount, fee);
        if (rejection != null) return "REJECTED " + rejection;

        a.balance = a.balance.subtract(amount.add(fee));
        as.addUsage(id, date, amount);
        rs.addFee(date, a.currency, fee);
        Transaction tx = new Transaction("WITHDRAW", date, id, "", amount, a.currency, fee, amount);
        return "OK TX-" + String.format("%06d", ts.save(tx).substring(3)) + " fee=" + fee + " " + a.currency;
    }

    public String deposit(String date, String id, BigDecimal amount) {
        Account a = as.getAccount(id);
        if (a == null) return "REJECTED UNKNOWN_ACCOUNT: " + id;
        a.balance = a.balance.add(amount);
        Transaction tx = new Transaction("DEPOSIT", date, id, "", amount, a.currency, new BigDecimal("0.00"), amount);
        return "OK TX-" + String.format("%06d", ts.save(tx).substring(3)) + " fee=0.00 " + a.currency;
    }

    public String reverse(String date, String txId) {
        Transaction tx = ts.get(txId);
        if (tx == null) return "REJECTED UNKNOWN_TX: " + txId;
        if (!"TRANSFER".equals(tx.verb)) return "REJECTED NOT_REVERSIBLE: " + txId + " is a " + tx.verb;
        if (tx.reversed) return "REJECTED ALREADY_REVERSED: " + txId;
        if (!tx.date.equals(date)) return "REJECTED REVERSAL_WINDOW: " + txId + " was made on " + tx.date;

        Account from = as.getAccount(tx.fromId);
        Account to = as.getAccount(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(tx.fee);
            rs.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        Transaction rev = new Transaction("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited);
        return "OK TX-" + String.format("%06d", ts.save(rev).substring(3)) + " reversed " + txId;
    }

    private String checkLimitAndFunds(String date, String id, Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = switch (a.tier) {
            case "STANDARD" -> new BigDecimal("5000.00");
            case "PREMIUM" -> new BigDecimal("20000.00");
            default -> new BigDecimal("50000.00");
        };
        if (as.usedToday(id, date).add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        }
        BigDecimal overdraft = "PREMIUM".equals(a.tier) ? new BigDecimal("500.00") : BigDecimal.ZERO;
        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + needed + " " + a.currency;
        }
        return null;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.List;

public class LedgerImpl implements Ledger {
    private final AccountStore as = new AccountStore();
    private final TransactionStore ts = new TransactionStore();
    private final AuditStore aus = new AuditStore();
    private final ReportStore rs = new ReportStore();
    private final CurrencyConverter cc = new CurrencyConverter();
    private final InstructionParser parser = new InstructionParser();
    private final TransactionEngine engine = new TransactionEngine(as, ts, rs, cc);

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.indexOf('|') >= 0) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        if (as.exists(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        as.openAccount(id, tier, currency, new BigDecimal(openingBalance).setScale(2));
    }

    public String balance(String id) {
        Account a = as.getAccount(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return aus.getLogs(); }
    public String dailyReport(String date) { return rs.generateReport(date); }

    public String submit(String line) {
        String verb = "???", date = "????-??-??";
        try {
            InstructionParser.Parsed p = parser.parse(line);
            verb = p.verb(); date = p.date();
            String res = switch (verb) {
                case "TRANSFER" -> engine.transfer(date, p.fields()[2], p.fields()[3], new BigDecimal(p.fields()[4]).setScale(2), p.fields()[5]);
                case "WITHDRAW" -> engine.withdraw(date, p.fields()[2], new BigDecimal(p.fields()[3]).setScale(2));
                case "DEPOSIT" -> engine.deposit(date, p.fields()[2], new BigDecimal(p.fields()[3]).setScale(2));
                case "REVERSE" -> engine.reverse(date, p.fields()[2]);
                default -> "REJECTED BAD_INSTRUCTION: unknown verb " + verb;
            };
            if (res.startsWith("REJECTED")) return reject(verb, date, res);
            if (res.contains("TX-")) {
                rs.recordOk(date);
                aus.record(verb, date, res.substring(0, res.indexOf(" fee=")));
                return res;
            }
            return res;
        } catch (InstructionParser.ParseException e) {
            return reject(verb, date, "REJECTED " + e.code + ": " + e.message);
        } catch (Exception e) {
            return reject(verb, date, "REJECTED BAD_AMOUNT: " + (line != null ? line : "null"));
        }
    }

    private String reject(String verb, String date, String res) {
        String code = res.contains(":") ? res.substring(res.indexOf(" REJECTED") + 9, res.indexOf(":")) : "BAD_INSTRUCTION";
        if (res.startsWith("REJECTED ")) code = res.substring(9, res.indexOf(":"));
        rs.recordRejected(date);
        aus.record(verb, date, "REJECTED " + code);
        return res.startsWith("REJECTED ") ? res : "REJECTED " + code + ": " + res;
    }
}

